CREATE TABLE DBP_DATA.ANGEBOT_ART_WUP_ZU (
   mandant_id                          INTEGER     NOT NULL COMMENT 'Mandant im DWH',
   angebot_nr                          VARCHAR(50)      NOT NULL COMMENT 'Numerische oder Alphanumerische Nummer des Angebots',
   art_id                              INTEGER     NOT NULL COMMENT 'Input: Artikel-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
   wup_id                              INTEGER     NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum',
   nb_id                               INTEGER     NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
   verkaufsorganisation_id             VARCHAR(4)       NOT NULL COMMENT 'Organisatorische Einheit, die für den Vertrieb bestimmter Produkte oder Dienstleistungen verantwortlich ist, z. B. KL = Kaufland.',
   art_basismenge_einh_id              VARCHAR(3)       COMMENT 'Einheit der Basismenge des Artikels, bspw. KG, L, ST, etc.',
   art_typ_cd                          VARCHAR(10)      COMMENT 'Code gibt den Typ des Artikels an: O = Orphan (Artikel hat keine mutter_wb_id), C = Child (Artikel hat eine mutter_wb_id), M = Mother (Artikel ist die mutter_wb_id).',
   art_gtin_id                         INTEGER     COMMENT 'GTIN des angebotenen Artikels in der Filiale',
   mutter_wb_id                        INTEGER     COMMENT 'Bei einer Serie von Artikeln mit gleicher Werbung ist hier die Artikel_ID des führenden Artikels (auch: Mutterartikel) hinterlegt.',
   art_posten_fg                       INTEGER     NOT NULL COMMENT 'Postenkennzeichen für Artikel, die nicht staendig im Sortiment sind. Angereichert jeweils aktuell aus dem Artikelstamm, da dort nicht historisiert.',
   art_prio_nr                         INTEGER     COMMENT 'Priorisiert den Artikel innerhalbt der Produktgruppe ()',
   art_theken_verkauf_fg               INTEGER     COMMENT 'Flag gibt an, ob der Artikel für das Angebot in dem Markt an der Theke verkauft wird (1) oder nicht (0).',
   art_nis_fg                          INTEGER     NOT NULL COMMENT 'Flag gibt an, ob Artikel sich neu (1) im Sortiment befindet oder nicht (0) ',
   art_national_fg                     INTEGER     NOT NULL COMMENT 'Flag gibt an, ob es sich um einen regionalen / nationalen Artikel handelt (1) oder in mehreren Ländern vorhanden ist (0).',
   art_export_werbemittel_fg           INTEGER     NOT NULL COMMENT 'Flag gibt an, ob der Artikel an die Werbemittel übertragen werden soll (1) oder nicht (0)',
   art_preisangabe_cd                  VARCHAR(10)      COMMENT 'Code gibt an welche Gesetze der Preisangabeverordnung eingehalten werden müssen. Je nach Verderblichkeit des Artikels können unterschiedliche Gesetze gelten: A = nicht verderblich (bspw. Non Food), B = verderblich, C verderblich mit längerer Gültigkeit',
   art_werbe_prod_gruppe_name          VARCHAR(500)     COMMENT 'Name der Werbe-Produktgruppe.Ein  Artikel kann für Angebote alternativen Produktgruppen zugeordnet werden. Diese sind nicht vergleichbar zu den Warengruppen im DWH.',
   gp_id                               INTEGER     COMMENT 'Geschäftspartner - ID (Lieferanten - ID)',
   opv_markt_fg                        INTEGER     NOT NULL COMMENT 'Flag gibt an, ob das Angebot in den Märkten ohne Preisvorteil (1) angezeigt wird.',
   opv_prospekt_fg                     INTEGER     NOT NULL COMMENT 'Flag gibt an, ob das Angebot in den Prospekten ohne Preisvorteil (1) angezeigt wird.',
   anz_bonuskauf_bezahlt               INTEGER     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, kann hier die Anzahl der Artikel stehen, die bezahlt werden müssen (Betrifft nicht alle Bonuskauf-Typen).',
   anz_bonuskauf_kauf                  INTEGER     COMMENT 'Handelt es sich bei dem Angebot  um einen Bonuskauf, kann hier die Anzahl an Artikeln stehen, die gekauft werden müssen. (Betrifft nicht alle Bonuskauf-Typen)',
   anz_bonuskauf_gratis                INTEGER     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, kann hier die Anzahl an Artikeln stehen, die kostenlos erhalten werden. (Betrifft nicht alle Bonuskauf Typen)',
   proz_bonuskauf_rabatt               NUMBER(29,5)     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf und der Rabatt ist prozentbezogen, kann hier der Rabatt in Prozent stehen (Betrifft nicht alle Bonuskauf Typen).',
   betrag_bonuskauf_rabatt             NUMBER(29,5)     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf und der Rabatt ist absolut, kann hier der Wert des Rabattes stehen (Betrifft nicht alle Bonuskauf Typen).',
   betrag_bonuskauf_min                NUMBER(29,5)     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, kann hier der Mindestbetrag (monetär) stehen, der erreicht werden muss, um die Bedingung für den Bonusby zu erfüllen (Betrifft nicht alle Bonuskauf Typen).',
   menge_bonuskauf_min                 NUMBER(29,5)     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, kann hier die Mindestmenge (absatzbezogen) stehen, die erreicht werden muss, um die Bedingung für den Bonusbuy zu erfüllen (Betrifft nicht alle Bonuskauf Typen).',
   bonuskauf_bedingung_id              INTEGER     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, ID der Bonuskauf Bedingung: Gibt an, ob der Kunde den Artikel kaufen / bezahlen muss (1) oder ihn als Bonus zum Kauf erhält (2).',
   bonuskauf_dimension_id              VARCHAR(10)      COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, ID der Bonuskauf Dimension: Gibt an, ob der Rabatt für ein Produkt oder mehrere Produkte gültig ist: 1 = Produkt, 2 = Produktgruppe, 3 = Warengruppe.',
   bonuskauf_produktvariante_id        VARCHAR(10)      COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, ID der Bonuskauf Produktvariante: Gibt an, in welcher Ausprägung die Produkte kombiniert werden müssen um den Rabatt zu erhalten: 0 = irgendein Produkt, 1 = selbes Produkt, 2, verschiedene Produkte',
   bonuskauf_rabattzuordnung_id        INTEGER     COMMENT 'Handelt es sich bei dem Angebot um einen Bonuskauf, ID der Bonuskauf Rabattzuordnung: Gibt an, für welches Produkt oder für welche Produkte der Rabatt gilt: 1 = alle Produkte, 2 = günstigstes Produkt, 3 = teuerstes Produkt.',
   wrg_id                              VARCHAR(3)       NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR',
   rabatt_typ_id                       INTEGER     COMMENT 'ID des Rabatt Typs. Gibt die Art des gewährten Rabattes an, bspw. Normalpreis (1), Rabattpreis (2), Absoluter Rabatt (3). etc.',
   preis_vk_brutto                     NUMBER(29,5)     COMMENT 'Regulärer Verkaufspreis des Artikels in dem Markt.',
   preis_vk_brutto_aktion              NUMBER(29,5)     COMMENT 'Angebotspreis des Artikels in dem Markt.',
   preis_vk_brutto_normalisiert        NUMBER(29,5)     COMMENT 'Auf die Basiseinheit normalisierter Preis des Artikels in dem Markt. Bsp.: Artikel enthält 2,5 Liter, Preis wird für 1 Liter berechnet.',
   preis_vk_brutto_stk                 NUMBER(29,5)     COMMENT 'Regulärer Verkaufspreis des Artikels pro Stück. Besteht der Artikel nur aus einem Stück entspricht dies dem preis_vk_brutto. Bspw. Preis einer einzelnen Flasche bei einer Kiste.',
   preis_vk_brutto_aktion_stk          NUMBER(29,5)     COMMENT 'Angebotspreis des Artikels pro Stück. Besteht der Artikel nur aus einem Stück entspricht dies dem preis_vk_brutto_aktion. Bspw. Preis einer Flasche in einer Kiste.',
   proz_preisnachlass                  NUMBER(29,5)     COMMENT 'Preisnachlass des Angebotspreises im Vergleich zum regulären Verkaufspreises in Prozent.',
   menge_prog_scm                      NUMBER(29,5)     COMMENT 'Prognostizierte Werbemengen von SCM (Supply Chain Management) die benötigt werden und beim Lieferanten bestellt werden sollen.',
   menge_prog_am                       NUMBER(29,5)     COMMENT 'Prognostiziertes Ziel der Absatzmenge von AM (Aktionsmanagement) durch Controlling vorgegeben.',
   betrag_prog_rohertrag_scm           NUMBER(29,5)     COMMENT 'Prognostizierter Rohertrag, der sich aus der SCM (Supply Chain Management) Prognose ergibt.',
   betrag_prog_pv                      NUMBER(29,5)     COMMENT 'Prognostizierter Wert der Preisveränderung (PV).',
   betrag_prog_umsatz_am               NUMBER(29,5)     COMMENT 'Prognostiziertes Umsatzziel von AM (Aktionsmanagemen), durch Controlling vorgegeben.',
   betrag_prog_umsatz_scm              NUMBER(29,5)     COMMENT 'Prognostiziertes Umsatzziel von SCM (Supply Chain Management)',
   preis_ek_nettonetto                 NUMBER(29,5)     COMMENT 'EK netto (Rechnungs-Einkaufspreis) abzüglich Skonto.',
   proz_art_rabatt                     NUMBER(29,5)     COMMENT 'Zusätzlich verhandelter Rabatt mit den Lieferanten in Prozent aus PMR. ZAR5',
   preis_ek_mep_vor_fwu                NUMBER(29,5)     COMMENT 'Markteinstandspreis vor Festwertumlage: Mit Einführung der Festwertumlage in KMO wurde als Vergleichswert der EK3Netto ohne (vor) der Festwertumlage eingeführt.',
   preis_ek_nettonetto_rabatt          NUMBER(29,5)     COMMENT 'Mit dem verhandelten Rabatt neu berechneter EK netto (Rechnungs-Einkaufspreis) abzüglich Skonto.',
   preis_ek_mep_vor_fwu_rabatt         NUMBER(29,5)     COMMENT 'Mit dem Rabatt neu berechneter Markteinstandspreis vor Festwertumlage: Mit Einführung der Festwertumlage in KMO wurde als Vergleichswert der EK3Netto ohne (vor) der Festwertumlage eingeführt.',
   proz_prog_spanne_ek_nettonetto      NUMBER(29,5)     COMMENT 'Mit EK netto netto berechnete prognostizierte Spanne (Rohertrag / Kassenumsatz) in Prozent.',
   proz_prog_spanne_ek_mep_vor_fwu     NUMBER(29,5)     COMMENT 'Mit EK MEP vor FWU berechnete prognostizierte Spanne (Rohertrag / Kassenumsatz) in Prozent.',
   proz_prog_spanne_ek_einstandspreis  NUMBER(29,5)     COMMENT 'Mit EK einstandspreis berechnete prognostizierte Spanne (Rohertrag / Kassenumsatz) in Prozent.',
   ek_preis_ermittlung_rabatt_typ_id   INTEGER     COMMENT 'Ziel Rabatt Typ aus PMR für ZAR5 Prozess. Sagt aus, welcher Rabatttyp bei der Ermittlung der Einkaufspreise für den angebotenen Artikel verwendet werden soll. 1 = Target EK Preism 2 = Target ZAR5',
   TD_UPDATE                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   TD_INSERT                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   CONSTRAINT PK_ANGEBOT_ART_WUP_ZU PRIMARY KEY (mandant_id, angebot_nr, art_id, wup_id, nb_id) NOT ENFORCED
)  COMMENT = 'Tabellle enthält Daten, wenn Angebote für Artikel in den Märkten verwendet werden.';
